    def get_geometry_info(self):
        """Get information about the chair geometry"""
        return {
            'vertex_count': self.vertex_count,
            'face_count': self.face_count,
            'bbox_size': self.bbox_size,
            'dimensions': {
                'width': self.bbox_size[0],
                'depth': self.bbox_size[1], 
                'height': self.bbox_size[2]
            }
        }


